from pathlib import Path

import test_logger
from aiohttp.test_utils import AioHTTPTestCase
from mongomock_motor import AsyncMongoMockClient

from server import make_app

test_logger.init_test_logger()

DOCS_DIR = Path(__file__).resolve().parents[1] / "templates" / "docs"


class VariantInfoPuzzleLinkTestCase(AioHTTPTestCase):
    async def get_application(self):
        return make_app(db_client=AsyncMongoMockClient(tz_aware=True))

    async def tearDownAsync(self):
        await self.client.close()

    def _ensure_variant_doc(self, key):
        # The documentation pages are generated by `yarn md`, which CI's Python job does not run.
        path = DOCS_DIR / f"{key}.html"
        if path.exists():
            return
        if not DOCS_DIR.exists():
            DOCS_DIR.mkdir(parents=True)
            self.addCleanup(lambda: DOCS_DIR.rmdir() if not any(DOCS_DIR.iterdir()) else None)
        path.write_text(f"<h1>{key}</h1>\n", encoding="utf-8")
        self.addCleanup(path.unlink, missing_ok=True)

    async def _get_page(self, key):
        self._ensure_variant_doc(key)
        response = await self.client.request("GET", f"/variants/{key}")
        self.assertEqual(response.status, 200)
        return await response.text()

    async def test_variant_with_puzzles_links_to_its_puzzles(self):
        text = await self._get_page("seirawan")

        self.assertEqual(text.count('class="button" href="/puzzle/seirawan"'), 1)

    async def test_variant_excluded_from_puzzles_has_no_puzzle_link(self):
        text = await self._get_page("antichess")

        self.assertNotIn('class="button" href="/puzzle/antichess"', text)

    async def test_960_variant_has_no_puzzle_link(self):
        text = await self._get_page("seirawan960")

        self.assertNotIn('class="button" href="/puzzle/seirawan960"', text)

    async def test_terminology_page_has_no_puzzle_link(self):
        text = await self._get_page("terminology")

        self.assertNotIn('class="button" href="/puzzle/', text)
